package com.sob.runehero;

/** Per-channel summary for the instrument readout: which instrument, how many notes, what register. */
final class ChannelInfo
{
    final int channel;
    final int program;   // GM instrument number, or -1 if unknown
    final int noteCount;
    final int minPitch;
    final int maxPitch;
    final double avgPitch;

    ChannelInfo(int channel, int program, int noteCount, int minPitch, int maxPitch, double avgPitch)
    {
        this.channel = channel;
        this.program = program;
        this.noteCount = noteCount;
        this.minPitch = minPitch;
        this.maxPitch = maxPitch;
        this.avgPitch = avgPitch;
    }

    boolean isDrums()
    {
        return channel == 9;
    }
}

package com.sob.runehero;

/**
 * One playable note in a generated chart: when to hit it, which fret/lane, and the original
 * MIDI pitch (kept for note coloring). {@code consumed} is flipped once the note has been
 * scored (hit) or swept as a miss, so the overlay and judge never double-count it.
 */
final class ChartNote
{
    final long hitTimeMs;
    final Lane lane;
    final int note;
    boolean consumed;

    ChartNote(long hitTimeMs, Lane lane, int note)
    {
        this.hitTimeMs = hitTimeMs;
        this.lane = lane;
        this.note = note;
    }
}

package com.sob.runehero;

/**
 * A difficulty mode bundles the lane set, density (how aggressively the chart is thinned), fall
 * speed (how long a note is visible while falling) and timing windows.
 *
 * The primary difficulty axis is LANE COUNT, not just density: lower difficulties keep MORE of
 * the song (denser) but on FEWER lanes, so they still feel like playing the song while being
 * easier. Throwing away most of the song (low density on all 5 lanes) just feels sparse and bad.
 *
 * MUST stay `public`: this enum is returned by {@link RuneHeroConfig#difficulty()}, and RuneLite's
 * config proxy (in the com.sun.proxy package) throws IllegalAccessError at runtime on a
 * package-private return type. Compilation and unit tests do NOT catch this — do not remove `public`.
 */
public enum Difficulty
{
    // 3 adjacent lanes (Inventory/Equipment/Prayer) — a clean contiguous strip, three fingers.
    EASY(new Lane[]{Lane.INVENTORY, Lane.EQUIPMENT, Lane.PRAYER}, 3.0, 2400, 80, 160),
    MEDIUM(new Lane[]{Lane.INVENTORY, Lane.EQUIPMENT, Lane.PRAYER}, 7.0, 1900, 60, 120),
    // All 5 lanes.
    HARD(Lane.ORDER, 8.0, 1500, 45, 90),
    EXPERT(Lane.ORDER, 99.0, 1200, 32, 65);

    private final Lane[] lanes;
    /** Maximum notes per second kept in the chart (99 ≈ no thinning = the full song). */
    final double targetNps;
    /** How long (ms) a note falls from spawn to the hit line. Smaller = faster. */
    final long leadTimeMs;
    /** |delta| ≤ this counts as Perfect. */
    final int perfectWindowMs;
    /** |delta| ≤ this counts as Good; beyond it the strum/tap misses. */
    final int goodWindowMs;

    Difficulty(Lane[] lanes, double targetNps, long leadTimeMs, int perfectWindowMs, int goodWindowMs)
    {
        this.lanes = lanes;
        this.targetNps = targetNps;
        this.leadTimeMs = leadTimeMs;
        this.perfectWindowMs = perfectWindowMs;
        this.goodWindowMs = goodWindowMs;
    }

    /** Lanes this mode uses, ordered left-to-right (ascending screen position). */
    Lane[] lanes()
    {
        return lanes;
    }

    /** Minimum spacing between kept notes, derived from {@link #targetNps}. */
    long minGapMs()
    {
        return Math.round(1000.0 / targetNps);
    }
}

package com.sob.runehero;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import javax.inject.Singleton;

/**
 * Owns the single source of truth for a playthrough: a {@link System#nanoTime()} clock and the
 * generated {@link ChartNote} list. Both the falling notes and the hit-judgment read from this
 * one clock, so there is nothing to sync to the (un-queryable) in-game audio position.
 *
 * Judging is fret + strum, keypress-only: {@link #setFret} tracks which frets are held;
 * {@link #onStrum} scores the nearest note in a held lane within the timing window. We never
 * read the active inventory tab.
 *
 * Key callbacks (setFret/onStrum) may arrive on a different thread from the render-thread sweep,
 * so mutating methods are synchronized and cross-thread fields are volatile.
 */
@Singleton
final class GameSession
{
    enum Judgment
    {
        PERFECT, GOOD, MISS
    }

    private volatile boolean running;
    private volatile boolean armed;          // waiting for the track to (re)start
    private volatile boolean armSawMusicOff;  // seen music go quiet since arming
    private volatile List<ChartNote> chart = new ArrayList<>();
    private volatile Difficulty difficulty = Difficulty.MEDIUM;
    private volatile long startNanos; // nanoTime at which chart time == 0

    private final Set<Lane> heldFrets = EnumSet.noneOf(Lane.class);

    private int score;
    private int combo;
    private int maxCombo;
    private int perfects;
    private int goods;
    private int misses;
    private int sweepCursor;

    private volatile Judgment lastJudgment;
    private volatile Lane lastJudgmentLane;
    private volatile long lastJudgmentNanos;

    // Per-lane hit/miss flash (for the overlay's feedback animation), indexed by Lane.ordinal().
    private final long[] laneFlashNanos = new long[Lane.COUNT];
    private final Judgment[] laneFlashJudge = new Judgment[Lane.COUNT];

    private volatile long endedNanos = Long.MIN_VALUE; // nanoTime a chart ended naturally (end card)

    /**
     * Begin a playthrough. {@code startNanos} is the {@link System#nanoTime()} value at which
     * chart time equals 0 — the caller anchors it (e.g. to the moment the live track restarted),
     * which is what keeps the falling notes lined up with the audio.
     */
    synchronized void start(List<ChartNote> newChart, Difficulty diff, long startNanos)
    {
        this.chart = newChart != null ? newChart : new ArrayList<>();
        this.difficulty = diff;
        this.startNanos = startNanos;
        heldFrets.clear();
        score = combo = maxCombo = perfects = goods = misses = 0;
        sweepCursor = 0;
        lastJudgment = null;
        lastJudgmentLane = null;
        Arrays.fill(laneFlashNanos, Long.MIN_VALUE);
        endedNanos = Long.MIN_VALUE;
        armed = false;
        running = !this.chart.isEmpty();
    }

    synchronized void stop()
    {
        running = false;
        armed = false;
        endedNanos = Long.MIN_VALUE; // manual stop — no end card
        heldFrets.clear();
    }

    /** Enter the "waiting for the track to restart" state (the player toggles Music off→on). */
    synchronized void arm()
    {
        running = false;
        armed = true;
        armSawMusicOff = false;
    }

    void disarm()
    {
        armed = false;
    }

    boolean isArmed()
    {
        return armed;
    }

    void setArmSawMusicOff(boolean v)
    {
        armSawMusicOff = v;
    }

    boolean armSawMusicOff()
    {
        return armSawMusicOff;
    }

    boolean isRunning()
    {
        return running;
    }

    Difficulty difficulty()
    {
        return difficulty;
    }

    List<ChartNote> chart()
    {
        return chart;
    }

    /** Milliseconds since chart time 0; negative during the count-in. */
    long elapsedMs(long nowNanos)
    {
        return (nowNanos - startNanos) / 1_000_000L;
    }

    synchronized void setFret(Lane lane, boolean down)
    {
        if (down)
        {
            heldFrets.add(lane);
        }
        else
        {
            heldFrets.remove(lane);
        }
    }

    boolean isFretHeld(Lane lane)
    {
        // EnumSet.contains is an O(1) bit test — safe to read without locking.
        return heldFrets.contains(lane);
    }

    /**
     * The player strummed. Score the nearest un-consumed note within the good window whose lane
     * fret is currently held. A strum with the wrong (or no) fret held, or with no note in range,
     * is an overstrum: no points and the combo breaks.
     */
    synchronized void onStrum(long nowNanos)
    {
        if (!running)
        {
            return;
        }
        long now = elapsedMs(nowNanos);
        int good = difficulty.goodWindowMs;

        ChartNote target = null;
        long bestDelta = Long.MAX_VALUE;
        for (ChartNote c : chart)
        {
            if (c.consumed || !heldFrets.contains(c.lane))
            {
                continue;
            }
            long delta = Math.abs(c.hitTimeMs - now);
            if (delta <= good && delta < bestDelta)
            {
                bestDelta = delta;
                target = c;
            }
        }

        if (target == null)
        {
            combo = 0;
            recordJudgment(Judgment.MISS, null, nowNanos);
            return;
        }

        target.consumed = true;
        award(bestDelta, target.lane, nowNanos);
    }

    /**
     * No-strum mode: pressing a fret IS the hit on that lane. Scores the nearest un-consumed
     * note in {@code lane} within the window; a press with no note in range breaks the combo.
     */
    synchronized void onLaneHit(Lane lane, long nowNanos)
    {
        if (!running)
        {
            return;
        }
        long now = elapsedMs(nowNanos);
        int good = difficulty.goodWindowMs;

        ChartNote target = null;
        long bestDelta = Long.MAX_VALUE;
        for (ChartNote c : chart)
        {
            if (c.consumed || c.lane != lane)
            {
                continue;
            }
            long delta = Math.abs(c.hitTimeMs - now);
            if (delta <= good && delta < bestDelta)
            {
                bestDelta = delta;
                target = c;
            }
        }

        if (target == null)
        {
            combo = 0;
            recordJudgment(Judgment.MISS, lane, nowNanos);
            return;
        }

        target.consumed = true;
        award(bestDelta, target.lane, nowNanos);
    }

    /** Streak multiplier, Guitar-Hero style: 1x, then 2x/3x/4x at combo 10/20/30+. */
    int multiplier()
    {
        return 1 + Math.min(combo / 10, 3);
    }

    private void award(long delta, Lane lane, long nowNanos)
    {
        int mult = multiplier();
        if (delta <= difficulty.perfectWindowMs)
        {
            perfects++;
            score += 100 * mult;
            combo++;
            recordJudgment(Judgment.PERFECT, lane, nowNanos);
        }
        else
        {
            goods++;
            score += 50 * mult;
            combo++;
            recordJudgment(Judgment.GOOD, lane, nowNanos);
        }
        if (combo > maxCombo)
        {
            maxCombo = combo;
        }
    }

    /** Per-frame: mark notes whose window has fully passed as misses, and end the chart. */
    synchronized void sweepMisses(long nowNanos)
    {
        if (!running)
        {
            return;
        }
        long now = elapsedMs(nowNanos);
        int good = difficulty.goodWindowMs;
        while (sweepCursor < chart.size())
        {
            ChartNote c = chart.get(sweepCursor);
            if (c.hitTimeMs + good >= now)
            {
                break; // still hittable
            }
            if (!c.consumed)
            {
                c.consumed = true;
                misses++;
                combo = 0;
                recordJudgment(Judgment.MISS, c.lane, nowNanos);
            }
            sweepCursor++;
        }

        if (sweepCursor >= chart.size() && !chart.isEmpty())
        {
            long lastHit = chart.get(chart.size() - 1).hitTimeMs;
            if (now > lastHit + good + 1500)
            {
                running = false;
                endedNanos = nowNanos;
            }
        }
    }

    private void recordJudgment(Judgment j, Lane lane, long nowNanos)
    {
        lastJudgment = j;
        lastJudgmentLane = lane;
        lastJudgmentNanos = nowNanos;
        if (lane != null)
        {
            laneFlashNanos[lane.ordinal()] = nowNanos;
            laneFlashJudge[lane.ordinal()] = j;
        }
    }

    /** nanoTime of the last hit/miss in this lane (for the overlay flash), or Long.MIN_VALUE. */
    long flashNanos(Lane lane)
    {
        return laneFlashNanos[lane.ordinal()];
    }

    Judgment flashJudgment(Lane lane)
    {
        return laneFlashJudge[lane.ordinal()];
    }

    int score()
    {
        return score;
    }

    int combo()
    {
        return combo;
    }

    int maxCombo()
    {
        return maxCombo;
    }

    int totalNotes()
    {
        return chart.size();
    }

    int hits()
    {
        return perfects + goods;
    }

    int perfects()
    {
        return perfects;
    }

    int misses()
    {
        return misses;
    }

    /** nanoTime the chart ended naturally (for the end card), or Long.MIN_VALUE. */
    long endedNanos()
    {
        return endedNanos;
    }

    Judgment lastJudgment()
    {
        return lastJudgment;
    }

    Lane lastJudgmentLane()
    {
        return lastJudgmentLane;
    }

    long lastJudgmentNanos()
    {
        return lastJudgmentNanos;
    }

    /** Notes whose fall window overlaps [now, now+leadTime]; a fresh list, safe to iterate. */
    List<ChartNote> visibleNotes(long nowNanos)
    {
        if (!running)
        {
            return Collections.emptyList();
        }
        long now = elapsedMs(nowNanos);
        long lead = difficulty.leadTimeMs;
        int good = difficulty.goodWindowMs;
        List<ChartNote> vis = new ArrayList<>();
        for (ChartNote c : chart)
        {
            if (c.consumed)
            {
                continue;
            }
            // Visible from when it spawns at the top until its window closes.
            if (c.hitTimeMs - lead <= now && c.hitTimeMs + good >= now)
            {
                vis.add(c);
            }
        }
        return vis;
    }
}

package com.sob.runehero;

/** General MIDI program (instrument) names and note-name formatting, for the channel readout. */
final class GmInstruments
{
    private static final String[] NOTE_NAMES =
        {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};

    private static final String[] GM = {
        "Acoustic Grand Piano", "Bright Acoustic Piano", "Electric Grand Piano", "Honky-tonk Piano",
        "Electric Piano 1", "Electric Piano 2", "Harpsichord", "Clavi",
        "Celesta", "Glockenspiel", "Music Box", "Vibraphone",
        "Marimba", "Xylophone", "Tubular Bells", "Dulcimer",
        "Drawbar Organ", "Percussive Organ", "Rock Organ", "Church Organ",
        "Reed Organ", "Accordion", "Harmonica", "Tango Accordion",
        "Acoustic Guitar (nylon)", "Acoustic Guitar (steel)", "Electric Guitar (jazz)", "Electric Guitar (clean)",
        "Electric Guitar (muted)", "Overdriven Guitar", "Distortion Guitar", "Guitar harmonics",
        "Acoustic Bass", "Electric Bass (finger)", "Electric Bass (pick)", "Fretless Bass",
        "Slap Bass 1", "Slap Bass 2", "Synth Bass 1", "Synth Bass 2",
        "Violin", "Viola", "Cello", "Contrabass",
        "Tremolo Strings", "Pizzicato Strings", "Orchestral Harp", "Timpani",
        "String Ensemble 1", "String Ensemble 2", "SynthStrings 1", "SynthStrings 2",
        "Choir Aahs", "Voice Oohs", "Synth Voice", "Orchestra Hit",
        "Trumpet", "Trombone", "Tuba", "Muted Trumpet",
        "French Horn", "Brass Section", "SynthBrass 1", "SynthBrass 2",
        "Soprano Sax", "Alto Sax", "Tenor Sax", "Baritone Sax",
        "Oboe", "English Horn", "Bassoon", "Clarinet",
        "Piccolo", "Flute", "Recorder", "Pan Flute",
        "Blown Bottle", "Shakuhachi", "Whistle", "Ocarina",
        "Lead 1 (square)", "Lead 2 (sawtooth)", "Lead 3 (calliope)", "Lead 4 (chiff)",
        "Lead 5 (charang)", "Lead 6 (voice)", "Lead 7 (fifths)", "Lead 8 (bass + lead)",
        "Pad 1 (new age)", "Pad 2 (warm)", "Pad 3 (polysynth)", "Pad 4 (choir)",
        "Pad 5 (bowed)", "Pad 6 (metallic)", "Pad 7 (halo)", "Pad 8 (sweep)",
        "FX 1 (rain)", "FX 2 (soundtrack)", "FX 3 (crystal)", "FX 4 (atmosphere)",
        "FX 5 (brightness)", "FX 6 (goblins)", "FX 7 (echoes)", "FX 8 (sci-fi)",
        "Sitar", "Banjo", "Shamisen", "Koto",
        "Kalimba", "Bag pipe", "Fiddle", "Shanai",
        "Tinkle Bell", "Agogo", "Steel Drums", "Woodblock",
        "Taiko Drum", "Melodic Tom", "Synth Drum", "Reverse Cymbal",
        "Guitar Fret Noise", "Breath Noise", "Seashore", "Bird Tweet",
        "Telephone Ring", "Helicopter", "Applause", "Gunshot",
    };

    private GmInstruments() {}

    static String name(int program)
    {
        if (program < 0)
        {
            return "Unknown";
        }
        if (program < GM.length)
        {
            return GM[program];
        }
        return "Program " + program;
    }

    /** MIDI note number -> name like "C4" (middle C = 60 = C4). */
    static String noteName(int midi)
    {
        if (midi < 0)
        {
            return "?";
        }
        return NOTE_NAMES[midi % 12] + (midi / 12 - 1);
    }
}

package com.sob.runehero;

import java.awt.Color;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Keybind;

/**
 * The frets — the inventory side-tabs players actually use: Combat, Inventory, Equipment,
 * Prayer, Magic. {@code screenPos} is the tab's left-to-right index within the full 7-tab main
 * row (Combat=0 … Magic=6), so notes draw over the correct icon while the unused Skills(1) and
 * Quests(2) tabs are skipped. The {@link Keybind} is only a default; the player rebinds each
 * fret in config. We never read which tab is open — judging is keypress-only.
 *
 * Each lane is themed as one of the five Catalytic runes; {@code runeItemId} is the OSRS item id
 * used to draw the real rune sprite as the falling note, and {@code color} tints the backing/glow.
 */
enum Lane
{
    COMBAT("Combat", 0, KeyEvent.VK_Z, 563, "Law", new Color(0x4C, 0x7D, 0xF0)),
    INVENTORY("Inventory", 3, KeyEvent.VK_X, 560, "Death", new Color(0xDA, 0xDA, 0xDA)),
    EQUIPMENT("Equipment", 4, KeyEvent.VK_C, 565, "Blood", new Color(0xC4, 0x20, 0x2A)),
    PRAYER("Prayer", 5, KeyEvent.VK_V, 566, "Soul", new Color(0x9D, 0xB8, 0xDF)),
    MAGIC("Magic", 6, KeyEvent.VK_B, 21880, "Wrath", new Color(0x33, 0xC5, 0x6B));

    final String label;
    final int screenPos;
    final Keybind defaultKey;
    final int runeItemId;
    final String runeName;
    final Color color;

    Lane(String label, int screenPos, int defaultKeyCode, int runeItemId, String runeName, Color color)
    {
        this.label = label;
        this.screenPos = screenPos;
        this.defaultKey = new Keybind(defaultKeyCode, 0);
        this.runeItemId = runeItemId;
        this.runeName = runeName;
        this.color = color;
    }

    static final Lane[] ORDER = values();
    static final int COUNT = ORDER.length; // 5
}

package com.sob.runehero;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Turns an extracted MIDI timeline into a playable single-lane chart.
 *
 * Because the player can only occupy one tab at a time, the chart MUST be monophonic — a
 * single melodic line, never a chord. The pipeline is:
 *   1. select source notes — a chosen SET of channels (Smart auto-pick or Manual A/B), or all
 *      non-drum channels merged if the set is empty,
 *   2. collapse to one note per instant (skyline: keep the highest pitch) + thin to the
 *      difficulty's note density,
 *   3. band each surviving note into one of the lanes by its deviation from the LOCAL pitch
 *      center (a rolling median), so melodic movement drives lane movement.
 *
 * Many tracks hand the melody between instruments, so charting one channel can go cold; charting
 * the right 1-2 channels (see {@link #smartChannels}) keeps the lead intact.
 *
 * Pure and client-free, so it is unit-testable in isolation.
 */
final class MapGenerator
{
    /** Window over which the local pitch center is taken, so each phrase recenters on the lanes. */
    private static final long BAND_WINDOW_MS = 6000;
    /**
     * Smart only adds a 3rd channel when the first two leave a CONTIGUOUS hole at least this long
     * — a stretch where another instrument has melody but our two lanes are silent. Brief pauses
     * are normal and don't trigger a third voice.
     */
    private static final long BIG_HOLE_MS = 4000;
    /** Semitones of deviation from the local center per lane step. Smaller = more lane movement. */
    private static final double SEMIS_PER_LANE = 3.0;

    private MapGenerator() {}

    /**
     * @param timeline   time-sorted note events from {@link MidiTrackResolver#flatten(byte[])}
     * @param difficulty controls density (thinning), lane set and timing
     * @param channels   the channels to merge; null/empty = all non-drum channels
     * @return monophonic chart, strictly increasing in hit time with ≥ {@code minGap} spacing
     */
    static List<ChartNote> generate(List<NoteEvent> timeline, Difficulty difficulty, int[] channels)
    {
        List<ChartNote> out = new ArrayList<>();
        if (timeline == null || timeline.isEmpty())
        {
            return out;
        }

        List<NoteEvent> source = (channels == null || channels.length == 0)
            ? tonalNotes(timeline)
            : onChannels(timeline, channels);
        if (source.isEmpty())
        {
            source = tonalNotes(timeline); // chosen channels silent — fall back to all tonal
        }
        if (source.isEmpty())
        {
            source = new ArrayList<>(timeline); // percussion-only track — fall back to all notes
        }
        if (source.isEmpty())
        {
            return out;
        }

        // Step 1: skyline collapse + density thinning -> kept notes as [timestampMs, pitch].
        long minGap = difficulty.minGapMs();
        long lastKept = Long.MIN_VALUE;
        List<long[]> kept = new ArrayList<>();
        int i = 0;
        int n = source.size();
        while (i < n)
        {
            long ts = source.get(i).timestampMs;
            NoteEvent best = source.get(i);
            int j = i + 1;
            while (j < n && source.get(j).timestampMs == ts)
            {
                NoteEvent cand = source.get(j);
                if (cand.note > best.note || (cand.note == best.note && cand.velocity > best.velocity))
                {
                    best = cand;
                }
                j++;
            }
            i = j;

            if (lastKept != Long.MIN_VALUE && ts - lastKept < minGap)
            {
                continue;
            }
            lastKept = ts;
            kept.add(new long[]{ts, best.note});
        }
        if (kept.isEmpty())
        {
            return out;
        }

        // Step 2: lane = local center lane ± deviation, banded into this difficulty's lane set.
        Lane[] lanes = difficulty.lanes();
        int laneN = lanes.length;
        int middle = (laneN - 1) / 2;
        int m = kept.size();
        for (int k = 0; k < m; k++)
        {
            long ts = kept.get(k)[0];
            int pitch = (int) kept.get(k)[1];
            double center = localMedianPitch(kept, k, ts);
            int lane = middle + (int) Math.round((pitch - center) / SEMIS_PER_LANE);
            if (lane < 0)
            {
                lane = 0;
            }
            else if (lane >= laneN)
            {
                lane = laneN - 1;
            }
            out.add(new ChartNote(ts, lanes[lane], pitch));
        }
        return out;
    }

    /**
     * Auto-pick the 1-2 channels that best carry the melody. Each candidate channel is scored on
     * register (melody sits high), pitch variety (a moving line, not a drone), activity, and —
     * weighted heavily — how MONOPHONIC it is (one note per onset). The melody is a single line;
     * pads and string ensembles play chords (many notes per onset), so the mono term steers the
     * pick to the real lead rather than a busy chordal background. Primary = top score; secondary
     * = the next channel that's still melodic (not a deep bass, not far weaker), so tracks whose
     * tune is split across two instruments get both. Empty array = no clear lead (use all).
     */
    static int[] smartChannels(List<NoteEvent> timeline)
    {
        if (timeline == null || timeline.isEmpty())
        {
            return new int[0];
        }
        int[] count = new int[16];          // raw note-ons (chords inflate this)
        int[] onsetTimes = new int[16];     // distinct onset timestamps (chord-agnostic activity)
        long[] sum = new long[16];
        boolean[][] seen = new boolean[16][128];
        int[] distinct = new int[16];
        long[] lastTs = new long[16];
        Arrays.fill(lastTs, Long.MIN_VALUE);
        for (NoteEvent e : timeline)
        {
            int c = e.channel;
            if (c < 0 || c >= 16 || c == 9)
            {
                continue; // skip drums
            }
            count[c]++;
            sum[c] += e.note;
            int p = e.note & 0x7F;
            if (!seen[c][p])
            {
                seen[c][p] = true;
                distinct[c]++;
            }
            if (e.timestampMs != lastTs[c])
            {
                onsetTimes[c]++;
                lastTs[c] = e.timestampMs;
            }
        }
        int busiest = 0;
        for (int c = 0; c < 16; c++)
        {
            busiest = Math.max(busiest, onsetTimes[c]);
        }
        if (busiest == 0)
        {
            return new int[0];
        }
        int minActivity = Math.max(8, (int) (0.12 * busiest));
        List<Integer> cand = new ArrayList<>();
        for (int c = 0; c < 16; c++)
        {
            if (onsetTimes[c] >= minActivity)
            {
                cand.add(c);
            }
        }
        if (cand.isEmpty())
        {
            return new int[0];
        }
        if (cand.size() == 1)
        {
            return new int[]{cand.get(0)};
        }

        double minAvg = 1e9, maxAvg = -1e9, minDis = 1e9, maxDis = -1e9, minOn = 1e9, maxOn = -1e9;
        for (int c : cand)
        {
            double a = (double) sum[c] / count[c];
            minAvg = Math.min(minAvg, a);
            maxAvg = Math.max(maxAvg, a);
            minDis = Math.min(minDis, distinct[c]);
            maxDis = Math.max(maxDis, distinct[c]);
            minOn = Math.min(minOn, onsetTimes[c]);
            maxOn = Math.max(maxOn, onsetTimes[c]);
        }

        double[] score = new double[16];
        double[] avg = new double[16];
        for (int c : cand)
        {
            avg[c] = (double) sum[c] / count[c];
            double mono = (double) onsetTimes[c] / count[c]; // 1.0 = pure single line; lower = chordal
            score[c] = norm(avg[c], minAvg, maxAvg)             // higher register
                + 0.7 * norm(distinct[c], minDis, maxDis)        // pitch variety
                + 0.5 * norm(onsetTimes[c], minOn, maxOn)        // activity
                + 1.5 * mono;                                    // single-line, not chordal
        }

        cand.sort((x, y) -> Double.compare(score[y], score[x]));
        int primary = cand.get(0);

        int secondary = -1;
        for (int i = 1; i < cand.size(); i++)
        {
            int c = cand.get(i);
            if (avg[c] >= avg[primary] - 18 && score[c] >= 0.5 * score[primary])
            {
                secondary = c;
                break;
            }
        }
        if (secondary < 0)
        {
            return new int[]{primary};
        }

        // Add a 3rd voice ONLY if the first two leave a BIG contiguous hole — a long stretch where
        // some other tonal channel has melody but our two are silent. Brief pauses (and genuine
        // song-wide silence, where nothing plays) don't count.
        long bucketMs = 700;
        Set<Long> covered = new HashSet<>();
        addBuckets(covered, timeline, primary, bucketMs);
        addBuckets(covered, timeline, secondary, bucketMs);
        if (longestHoleMs(timeline, new int[]{primary, secondary}) < BIG_HOLE_MS)
        {
            return new int[]{primary, secondary}; // only brief pauses — two voices is enough
        }

        // There's a big hole: fill it with whatever tonal channel covers the most of it. A gap-filler
        // typically plays ONLY during the gap, so it has few total notes and would fail the global
        // activity filter — search ALL tonal channels here, not just the busy candidate list.
        int tertiary = -1;
        int bestNew = 0;
        for (int c = 0; c < 16; c++)
        {
            if (c == 9 || c == primary || c == secondary || count[c] < 8)
            {
                continue;
            }
            if ((double) sum[c] / count[c] < avg[primary] - 24)
            {
                continue; // a deep bass relative to the lead — skip
            }
            int newB = newBuckets(covered, timeline, c, bucketMs);
            if (newB > bestNew)
            {
                bestNew = newB;
                tertiary = c;
            }
        }
        if (tertiary >= 0 && bestNew * bucketMs >= BIG_HOLE_MS / 2)
        {
            return new int[]{primary, secondary, tertiary};
        }
        return new int[]{primary, secondary};
    }

    /** Longest gap (ms) between consecutive notes in a generated chart — the actual on-screen pause. */
    static long longestNoteGapMs(List<ChartNote> chart)
    {
        long longest = 0;
        for (int i = 1; i < chart.size(); i++)
        {
            long gap = chart.get(i).hitTimeMs - chart.get(i - 1).hitTimeMs;
            if (gap > longest)
            {
                longest = gap;
            }
        }
        return longest;
    }

    /** Longest contiguous stretch (ms) where some tonal channel has melody but none of {@code channels} play. */
    static long longestHoleMs(List<NoteEvent> timeline, int[] channels)
    {
        if (timeline == null || timeline.isEmpty())
        {
            return 0;
        }
        long bucketMs = 700;
        Set<Long> covered = new HashSet<>();
        for (int c : channels)
        {
            addBuckets(covered, timeline, c, bucketMs);
        }
        Set<Long> songBuckets = new HashSet<>();
        long minB = Long.MAX_VALUE;
        long maxB = Long.MIN_VALUE;
        for (NoteEvent e : timeline)
        {
            if (e.channel == 9)
            {
                continue;
            }
            long b = e.timestampMs / bucketMs;
            songBuckets.add(b);
            minB = Math.min(minB, b);
            maxB = Math.max(maxB, b);
        }
        if (songBuckets.isEmpty())
        {
            return 0;
        }
        long longest = 0;
        long run = 0;
        for (long b = minB; b <= maxB; b++)
        {
            if (songBuckets.contains(b) && !covered.contains(b))
            {
                run++;
                longest = Math.max(longest, run);
            }
            else
            {
                run = 0;
            }
        }
        return longest * bucketMs;
    }

    private static void addBuckets(Set<Long> set, List<NoteEvent> timeline, int channel, long bucketMs)
    {
        for (NoteEvent e : timeline)
        {
            if (e.channel == channel)
            {
                set.add(e.timestampMs / bucketMs);
            }
        }
    }

    private static int newBuckets(Set<Long> covered, List<NoteEvent> timeline, int channel, long bucketMs)
    {
        Set<Long> b = new HashSet<>();
        for (NoteEvent e : timeline)
        {
            if (e.channel == channel)
            {
                long k = e.timestampMs / bucketMs;
                if (!covered.contains(k))
                {
                    b.add(k);
                }
            }
        }
        return b.size();
    }

    private static double norm(double v, double lo, double hi)
    {
        return hi > lo ? (v - lo) / (hi - lo) : 0.0;
    }

    /** Median pitch of the kept notes within ±{@link #BAND_WINDOW_MS} of {@code kept[k]}. */
    private static double localMedianPitch(List<long[]> kept, int k, long ts)
    {
        int lo = k;
        int hi = k;
        while (lo - 1 >= 0 && ts - kept.get(lo - 1)[0] <= BAND_WINDOW_MS)
        {
            lo--;
        }
        while (hi + 1 < kept.size() && kept.get(hi + 1)[0] - ts <= BAND_WINDOW_MS)
        {
            hi++;
        }
        int cnt = hi - lo + 1;
        int[] pitches = new int[cnt];
        for (int x = 0; x < cnt; x++)
        {
            pitches[x] = (int) kept.get(lo + x)[1];
        }
        Arrays.sort(pitches);
        int mid = cnt / 2;
        return (cnt % 2 == 0) ? (pitches[mid - 1] + pitches[mid]) / 2.0 : pitches[mid];
    }

    private static List<NoteEvent> onChannels(List<NoteEvent> timeline, int[] channels)
    {
        boolean[] want = new boolean[16];
        for (int c : channels)
        {
            if (c >= 0 && c < 16)
            {
                want[c] = true;
            }
        }
        List<NoteEvent> r = new ArrayList<>();
        for (NoteEvent e : timeline)
        {
            if (e.channel >= 0 && e.channel < 16 && want[e.channel])
            {
                r.add(e);
            }
        }
        return r;
    }

    /** All note-ons except channel 9 (GM percussion), preserving time order. */
    private static List<NoteEvent> tonalNotes(List<NoteEvent> timeline)
    {
        List<NoteEvent> r = new ArrayList<>();
        for (NoteEvent e : timeline)
        {
            if (e.channel != 9)
            {
                r.add(e);
            }
        }
        return r;
    }
}

package com.sob.runehero;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;

/**
 * Reads raw OSRS music bytes by archive id, using the running RuneLite client's
 * own cache accessor (Client.getIndex). The bytes returned are in Jagex's
 * packed format and must be passed through {@link com.sob.runehero.vendored.TrackLoader}
 * to be converted into standard SMF.
 *
 * Index numbers come from the OSRS cache layout: 6 = music tracks, 11 = jingles.
 */
@Slf4j
@Singleton
final class MidiCacheLoader
{
    private static final int INDEX_MUSIC_TRACKS = 6;
    private static final int INDEX_MUSIC_JINGLES = 11;

    private final Client client;

    @Inject
    MidiCacheLoader(Client client)
    {
        this.client = client;
    }

    byte[] load(int archiveId, boolean jingle)
    {
        try
        {
            int indexId = jingle ? INDEX_MUSIC_JINGLES : INDEX_MUSIC_TRACKS;
            IndexDataBase index = client.getIndex(indexId);
            if (index == null)
            {
                log.warn("musicviz: client returned null for index {}", indexId);
                return null;
            }
            byte[] bytes = index.loadData(archiveId, 0);
            if (bytes == null || bytes.length == 0)
            {
                log.debug("musicviz: index {} archive {} returned no bytes", indexId, archiveId);
                return null;
            }
            return bytes;
        }
        catch (Throwable t)
        {
            log.warn("musicviz: failed to load archive {} (jingle={})", archiveId, jingle, t);
            return null;
        }
    }
}

package com.sob.runehero;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import com.sob.runehero.vendored.SmfParser;
import com.sob.runehero.vendored.TrackDefinition;
import com.sob.runehero.vendored.TrackLoader;

@Slf4j
final class MidiTrackResolver
{
    private MidiTrackResolver() {}

    static List<NoteEvent> flatten(byte[] cacheBytes) throws Exception
    {
        TrackDefinition def = new TrackLoader().load(cacheBytes);
        if (def == null || def.midi == null || def.midi.length == 0)
        {
            return Collections.emptyList();
        }

        SmfParser.Parsed parsed = SmfParser.parse(def.midi);
        if (parsed.divisionPpq <= 0) return Collections.emptyList();

        long[] tempoMap = buildTempoMap(parsed.tempoChanges);

        List<NoteEvent> out = new ArrayList<>(parsed.noteOns.size());
        for (SmfParser.NoteOn n : parsed.noteOns)
        {
            long ms = tickToMs(n.tick, tempoMap, parsed.divisionPpq);
            out.add(new NoteEvent(ms, n.channel, n.note, n.velocity));
        }
        Collections.sort(out);
        return out;
    }

    /**
     * Per-channel summary (instrument, note count, register) for the in-game readout, so the
     * player can pick the melody channel. Sorted by note count, descending.
     */
    static List<ChannelInfo> analyze(byte[] cacheBytes) throws Exception
    {
        TrackDefinition def = new TrackLoader().load(cacheBytes);
        if (def == null || def.midi == null || def.midi.length == 0)
        {
            return Collections.emptyList();
        }
        SmfParser.Parsed parsed = SmfParser.parse(def.midi);

        int[] count = new int[16];
        long[] sum = new long[16];
        int[] min = new int[16];
        int[] max = new int[16];
        Arrays.fill(min, Integer.MAX_VALUE);
        Arrays.fill(max, Integer.MIN_VALUE);
        for (SmfParser.NoteOn n : parsed.noteOns)
        {
            if (n.channel < 0 || n.channel >= 16)
            {
                continue;
            }
            count[n.channel]++;
            sum[n.channel] += n.note;
            min[n.channel] = Math.min(min[n.channel], n.note);
            max[n.channel] = Math.max(max[n.channel], n.note);
        }

        List<ChannelInfo> out = new ArrayList<>();
        for (int c = 0; c < 16; c++)
        {
            if (count[c] == 0)
            {
                continue;
            }
            int program = parsed.programByChannel[c];
            out.add(new ChannelInfo(c, program, count[c], min[c], max[c], (double) sum[c] / count[c]));
        }
        out.sort((a, b) -> Integer.compare(b.noteCount, a.noteCount));
        return out;
    }

    /**
     * Flatten the SMF tempo events (microseconds per quarter note at a tick)
     * into a sparse [tick, usPerQuarter, ...] table sorted by tick. Tick 0
     * defaults to 120 BPM (500000 us/q) if no earlier tempo is specified.
     */
    private static long[] buildTempoMap(List<SmfParser.TempoChange> changes)
    {
        List<long[]> rows = new ArrayList<>(changes.size() + 1);
        rows.add(new long[]{0L, 500_000L});
        for (SmfParser.TempoChange tc : changes)
        {
            rows.add(new long[]{tc.tick, tc.microsPerQuarter});
        }
        rows.sort((a, b) -> Long.compare(a[0], b[0]));
        long[] flat = new long[rows.size() * 2];
        for (int i = 0; i < rows.size(); i++)
        {
            flat[i * 2] = rows.get(i)[0];
            flat[i * 2 + 1] = rows.get(i)[1];
        }
        return flat;
    }

    private static long tickToMs(long targetTick, long[] tempoMap, int ppq)
    {
        long ms = 0;
        long prevTick = 0;
        long prevUsPerQ = 500_000L;
        for (int i = 0; i < tempoMap.length; i += 2)
        {
            long tick = tempoMap[i];
            long usPerQ = tempoMap[i + 1];
            if (tick >= targetTick)
            {
                ms += ((targetTick - prevTick) * prevUsPerQ) / (ppq * 1000L);
                return ms;
            }
            ms += ((tick - prevTick) * prevUsPerQ) / (ppq * 1000L);
            prevTick = tick;
            prevUsPerQ = usPerQ;
        }
        ms += ((targetTick - prevTick) * prevUsPerQ) / (ppq * 1000L);
        return ms;
    }
}

package com.sob.runehero;

final class NoteEvent implements Comparable<NoteEvent>
{
    final long timestampMs;
    final int channel;
    final int note;
    final int velocity;

    NoteEvent(long timestampMs, int channel, int note, int velocity)
    {
        this.timestampMs = timestampMs;
        this.channel = channel;
        this.note = note;
        this.velocity = velocity;
    }

    @Override
    public int compareTo(NoteEvent other)
    {
        return Long.compare(timestampMs, other.timestampMs);
    }
}

