    @Inject
    RuneHeroOverlay(GameSession session, TabBounds tabBounds, RuneHeroConfig config,
        ItemManager itemManager, Client client)
    {
        this.session = session;
        this.tabBounds = tabBounds;
        this.config = config;
        this.itemManager = itemManager;
        this.client = client;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        long nowNanos = System.nanoTime();

        if (session.isArmed() && !session.isRunning())
        {
            drawArmedIndicator(g);
            return null;
        }
        if (!session.isRunning())
        {
            drawEndCard(g, nowNanos);
            return null;
        }

        Lane[] active = session.difficulty().lanes();
        Rectangle[] cells = computeCells(active);
        if (cells == null)
        {
            return null;
        }
        Rectangle[] cellByLane = new Rectangle[Lane.COUNT];
        for (int i = 0; i < active.length; i++)
        {
            cellByLane[active[i].ordinal()] = cells[i];
        }

        session.sweepMisses(nowNanos);

        long now = session.elapsedMs(nowNanos);
        long lead = session.difficulty().leadTimeMs;
        int fallDistance = config.fallDistance();
        int hitLineY = cells[0].y;
        int topY = hitLineY - fallDistance;
        int combo = session.combo();
        float comboT = Math.min(combo / COMBO_FULL, 1f);
        boolean center = config.notePosition() == RuneHeroConfig.NotePosition.CENTER;
        boolean runes = config.runeIcons();

        if (combo == 0)
        {
            lastMilestone = 0;
        }

        Stroke prevStroke = g.getStroke();

        // Lane tracks (rising "flame" that warms toward gold with the combo), targets, held frets.
        for (int i = 0; i < active.length; i++)
        {
            Lane lane = active[i];
            Rectangle cell = cells[i];
            int laneW = Math.max(cell.width - 2, 6);
            int lx = cell.x + cell.width / 2 - laneW / 2;

            Color flameTop = new Color(255, 255, 255, 14);
            Color flameBottom = lerp(Color.WHITE, FLAME, comboT, 24 + (int) (comboT * 150));
            g.setPaint(new GradientPaint(lx, topY, flameTop, lx, hitLineY, flameBottom));
            g.fillRect(lx, topY, laneW, fallDistance);

            if (center)
            {
                g.setColor(new Color(0, 0, 0, 130));
                g.fillRoundRect(cell.x, cell.y, cell.width, cell.height, 8, 8);
                BufferedImage img = runes ? runeImage(lane) : null;
                if (img != null)
                {
                    g.drawImage(img, cell.x + 2, cell.y + 2, cell.width - 4, cell.height - 4, null);
                }
                else
                {
                    g.setColor(alpha(lane.color, 150));
                    g.fillRoundRect(cell.x + 3, cell.y + 3, cell.width - 6, cell.height - 6, 6, 6);
                }
                g.setColor(alpha(lane.color, 170));
                g.setStroke(new BasicStroke(1.5f));
                g.drawRoundRect(cell.x, cell.y, cell.width, cell.height, 8, 8);
            }

            if (session.isFretHeld(lane))
            {
                g.setColor(alpha(lane.color, 110));
                g.fillRect(cell.x, cell.y, cell.width, cell.height);
            }
        }

        // Hit line — brightens and thickens toward gold as the combo grows.
        Rectangle first = cells[0];
        Rectangle last = cells[active.length - 1];
        g.setColor(lerp(Color.WHITE, GOLD, comboT, 190 + (int) (comboT * 65)));
        g.setStroke(new BasicStroke(2f + comboT * 2f));
        g.drawLine(first.x, hitLineY, last.x + last.width, hitLineY);

        // Falling notes.
        for (ChartNote note : session.visibleNotes(nowNanos))
        {
            Rectangle cell = cellByLane[note.lane.ordinal()];
            if (cell == null)
            {
                continue;
            }
            int cx = cell.x + cell.width / 2;
            double progress = (double) (note.hitTimeMs - now) / lead;
            if (progress < 0)
            {
                progress = 0;
            }
            int y = (int) (hitLineY - progress * fallDistance);
            int size = Math.max(Math.min(cell.width, cell.height) - 2, 10);
            BufferedImage img = runes ? runeImage(note.lane) : null;
            g.setColor(alpha(note.lane.color, 70));
            g.fillRoundRect(cx - size / 2, y - size / 2, size, size, 8, 8);
            if (img != null)
            {
                g.drawImage(img, cx - size / 2, y - size / 2, size, size, null);
            }
            g.setColor(alpha(note.lane.color.brighter(), 200));
            g.setStroke(new BasicStroke(1.5f));
            g.drawRoundRect(cx - size / 2, y - size / 2, size, size, 8, 8);
        }

        // Per-lane flashes + spawn hit-burst shards on new hits.
        for (int i = 0; i < active.length; i++)
        {
            maybeSpawnBurst(active[i], cells[i], hitLineY, nowNanos);
            drawLaneFlash(g, cells[i], hitLineY, active[i], nowNanos);
        }
        drawShards(g, nowNanos);

        g.setStroke(prevStroke);
        drawHud(g, first, last, topY, hitLineY, comboT, combo, nowNanos);
        return null;
    }

    private Rectangle[] computeCells(Lane[] active)
    {
        if (config.notePosition() == RuneHeroConfig.NotePosition.CENTER)
        {
            int n = active.length;
            int cw = client.getCanvasWidth();
            int ch = client.getCanvasHeight();
            if (cw <= 0 || ch <= 0)
            {
                return null;
            }
            int cell = 42;
            int gap = 12;
            int totalW = n * cell + (n - 1) * gap;
            int x0 = (cw - totalW) / 2;
            int fall = config.fallDistance();
            int playH = fall + cell;
            int topAreaY = Math.max(70, (ch - playH) / 2 + 30);
            int hitY = topAreaY + fall;
            Rectangle[] cells = new Rectangle[n];
            for (int i = 0; i < n; i++)
            {
                cells[i] = new Rectangle(x0 + i * (cell + gap), hitY, cell, cell);
            }
            return cells;
        }

        Rectangle[] tabs = tabBounds.resolve();
        if (tabs == null || tabs.length < TabBounds.MAIN_TAB_COUNT)
        {
            return null;
        }
        Rectangle[] cells = new Rectangle[active.length];
        for (int i = 0; i < active.length; i++)
        {
            cells[i] = tabs[active[i].screenPos];
        }
        return cells;
    }

    private void maybeSpawnBurst(Lane lane, Rectangle cell, int hitLineY, long nowNanos)
    {
        long fn = session.flashNanos(lane);
        if (fn == Long.MIN_VALUE || fn == lastFlashSpawned[lane.ordinal()])
        {
            return;
        }
        lastFlashSpawned[lane.ordinal()] = fn;
        GameSession.Judgment j = session.flashJudgment(lane);
        if (j == GameSession.Judgment.MISS)
        {
            return;
        }
        int count = j == GameSession.Judgment.PERFECT ? 9 : 4;
        if (shards.size() > 200)
        {
            return;
        }
        int cx = cell.x + cell.width / 2;
        for (int i = 0; i < count; i++)
        {
            double ang = -Math.PI / 2 + (rng.nextDouble() - 0.5) * Math.PI; // upward fan
            double spd = 120 + rng.nextDouble() * 180;
            Shard s = new Shard();
            s.x0 = cx;
            s.y0 = hitLineY;
            s.vx = Math.cos(ang) * spd;
            s.vy = Math.sin(ang) * spd;
            s.born = fn;
            s.color = lane.color;
            shards.add(s);
        }
    }

    private void drawShards(Graphics2D g, long nowNanos)
    {
        for (Iterator<Shard> it = shards.iterator(); it.hasNext(); )
        {
            Shard s = it.next();
            double age = (nowNanos - s.born) / 1_000_000_000.0;
            if (age < 0 || age >= SHARD_LIFE_SEC)
            {
                it.remove();
                continue;
            }
            int x = (int) (s.x0 + s.vx * age);
            int y = (int) (s.y0 + s.vy * age + 0.5 * SHARD_GRAVITY * age * age);
            int a = (int) (220 * (1 - age / SHARD_LIFE_SEC));
            g.setColor(alpha(s.color, a));
            g.fillOval(x - 2, y - 2, 5, 5);
        }
    }

    private void drawLaneFlash(Graphics2D g, Rectangle cell, int hitLineY, Lane lane, long nowNanos)
    {
        long fn = session.flashNanos(lane);
        if (fn == Long.MIN_VALUE)
        {
            return;
        }
        long age = (nowNanos - fn) / 1_000_000L;
        if (age < 0 || age >= FLASH_MS)
        {
            return;
        }
        float p = age / (float) FLASH_MS;
        Color base = judgeColor(session.flashJudgment(lane));
        int cx = cell.x + cell.width / 2;
        int a = (int) (220 * (1f - p));

        g.setColor(alpha(base, (int) (a * 0.45f)));
        g.fillRect(cell.x, cell.y, cell.width, cell.height);

        int r = (int) (cell.width * 0.45f + p * cell.width);
        g.setColor(alpha(base, a));
        g.setStroke(new BasicStroke(2.5f));
        g.drawOval(cx - r, hitLineY - r, r * 2, r * 2);
    }

    private void drawHud(Graphics2D g, Rectangle first, Rectangle last, int topY, int hitLineY,
        float comboT, int combo, long nowNanos)
    {
        int left = first.x;
        int centerX = (first.x + last.x + last.width) / 2;
        Font baseFont = g.getFont();

        g.setFont(baseFont.deriveFont(Font.BOLD, 12f));
        String score = "Score " + session.score();
        int scoreY = Math.max(topY - 8, 14);
        g.setColor(Color.BLACK);
        g.drawString(score, left + 1, scoreY + 1);
        g.setColor(Color.WHITE);
        g.drawString(score, left, scoreY);

        if (combo >= 2)
        {
            g.setFont(baseFont.deriveFont(Font.BOLD, 13f + comboT * 9f));
            String text = Integer.toString(combo);
            int w = g.getFontMetrics().stringWidth(text);
            int cy = Math.max(topY - 8, 16);
            g.setColor(Color.BLACK);
            g.drawString(text, centerX - w / 2 + 1, cy + 1);
            g.setColor(lerp(Color.WHITE, GOLD, comboT, 255));
            g.drawString(text, centerX - w / 2, cy);

            int mult = session.multiplier();
            if (mult > 1)
            {
                g.setFont(baseFont.deriveFont(Font.BOLD, 11f + comboT * 4f));
                String mt = "x" + mult;
                int mw = g.getFontMetrics().stringWidth(mt);
                g.setColor(Color.BLACK);
                g.drawString(mt, centerX - mw / 2 + 1, cy + 17);
                g.setColor(alpha(GOLD, 255));
                g.drawString(mt, centerX - mw / 2, cy + 16);
            }
        }

        for (int m : MILESTONES)
        {
            if (combo >= m && m > lastMilestone)
            {
                lastMilestone = m;
                milestoneValue = m;
                milestoneNanos = nowNanos;
            }
        }
        if (milestoneNanos != Long.MIN_VALUE)
        {
            long mAge = (nowNanos - milestoneNanos) / 1_000_000L;
            if (mAge >= 0 && mAge < MILESTONE_LIFE_MS)
            {
                float mp = mAge / (float) MILESTONE_LIFE_MS;
                int a = (int) (255 * (1f - mp));
                float pop = 1f + 0.5f * (1f - Math.min(mp * 3f, 1f));
                g.setFont(baseFont.deriveFont(Font.BOLD, 26f * pop));
                String text = milestoneValue + " COMBO!";
                int w = g.getFontMetrics().stringWidth(text);
                int my = Math.max(topY - 34, 40);
                g.setColor(new Color(0, 0, 0, a));
                g.drawString(text, centerX - w / 2 + 2, my + 2);
                g.setColor(alpha(GOLD, a));
                g.drawString(text, centerX - w / 2, my);
            }
        }

        if (!config.showJudgment())
        {
            return;
        }
        GameSession.Judgment j = session.lastJudgment();
        if (j == null)
        {
            return;
        }
        long age = (nowNanos - session.lastJudgmentNanos()) / 1_000_000L;
        if (age < 0 || age >= JUDGMENT_LIFE_MS)
        {
            return;
        }
        int alpha = (int) (255 * (1f - age / (float) JUDGMENT_LIFE_MS));
        g.setFont(baseFont.deriveFont(Font.BOLD, 15f));
        g.setColor(alpha(judgeColor(j), Math.max(0, alpha)));
        g.drawString(j.name(), left, hitLineY - 8);
    }

    private void drawEndCard(Graphics2D g, long nowNanos)
    {
        long e = session.endedNanos();
        if (e == Long.MIN_VALUE)
        {
            return;
        }
        long age = (nowNanos - e) / 1_000_000L;
        if (age < 0 || age >= END_CARD_MS)
        {
            return;
        }
        int total = session.totalNotes();
        if (total == 0)
        {
            return;
        }
        int cw = client.getCanvasWidth();
        int ch = client.getCanvasHeight();
        if (cw <= 0 || ch <= 0)
        {
            return;
        }

        int hits = session.hits();
        int acc = (int) Math.round(100.0 * hits / total);
        String rank = acc >= 98 ? "S" : acc >= 95 ? "A" : acc >= 88 ? "B"
            : acc >= 75 ? "C" : acc >= 60 ? "D" : "E";
        boolean fc = session.misses() == 0;

        int alpha = 255;
        long fade = 700;
        if (age > END_CARD_MS - fade)
        {
            alpha = (int) (255 * (END_CARD_MS - age) / (double) fade);
        }
        alpha = Math.max(0, Math.min(255, alpha));

        int pw = 280;
        int ph = 156;
        int px = (cw - pw) / 2;
        int py = (ch - ph) / 2;
        g.setColor(new Color(0, 0, 0, (int) (alpha * 0.72f)));
        g.fillRoundRect(px, py, pw, ph, 16, 16);
        g.setColor(alpha(GOLD, alpha));
        g.setStroke(new BasicStroke(2f));
        g.drawRoundRect(px, py, pw, ph, 16, 16);

        Font bf = g.getFont();
        int midX = cw / 2;

        g.setFont(bf.deriveFont(Font.BOLD, 40f));
        drawCentered(g, "RANK " + rank, midX, py + 52, alpha(rankColor(rank), alpha), alpha);

        int statsY = py + 84;
        if (fc)
        {
            g.setFont(bf.deriveFont(Font.BOLD, 16f));
            drawCentered(g, "FULL COMBO!", midX, py + 80, alpha(GOLD, alpha), alpha);
            statsY = py + 104;
        }

        g.setFont(bf.deriveFont(Font.BOLD, 13f));
        drawCentered(g, hits + "/" + total + "  (" + acc + "%)", midX, statsY, alpha(Color.WHITE, alpha), alpha);
        drawCentered(g, "Max combo " + session.maxCombo() + "    Score " + session.score(),
            midX, statsY + 20, alpha(Color.WHITE, alpha), alpha);
    }

    private void drawCentered(Graphics2D g, String text, int centerX, int y, Color color, int shadowAlpha)
    {
        FontMetrics fm = g.getFontMetrics();
        int w = fm.stringWidth(text);
        g.setColor(new Color(0, 0, 0, Math.max(0, Math.min(255, shadowAlpha))));
        g.drawString(text, centerX - w / 2 + 1, y + 1);
        g.setColor(color);
        g.drawString(text, centerX - w / 2, y);
    }

    private void drawArmedIndicator(Graphics2D g)
    {
        Lane[] active = session.difficulty().lanes();
        Rectangle[] cells = computeCells(active);
        if (cells == null)
        {
            return;
        }
        Rectangle first = cells[0];
        Rectangle last = cells[active.length - 1];
        int left = first.x;
        int width = Math.max((last.x + last.width) - left, 300);
        int top = first.y - config.fallDistance();
        int boxH = 64;

        g.setColor(new Color(0, 0, 0, 185));
        g.fillRect(left, top, width, boxH);
        g.setColor(GOLD);
        g.drawRect(left, top, width, boxH);

        Font baseFont = g.getFont();
        g.setFont(baseFont.deriveFont(Font.BOLD, 20f));
        g.setColor(GOLD);
        g.drawString("RUNEHERO — ARMED", left + 10, top + 26);
        g.setFont(baseFont.deriveFont(Font.BOLD, 15f));
        g.setColor(Color.WHITE);
        String hint = session.armSawMusicOff()
            ? "Now turn Music back ON to start ▶"
            : "Turn Music OFF then ON to sync to the song";
        g.drawString(hint, left + 10, top + 50);
    }

    private BufferedImage runeImage(Lane lane)
    {
        int i = lane.ordinal();
        if (runeImg[i] == null)
        {
            runeImg[i] = itemManager.getImage(lane.runeItemId);
        }
        return runeImg[i];
    }

    private static Color rankColor(String rank)
    {
        switch (rank)
        {
            case "S":
                return GOLD;
            case "A":
                return PERFECT;
            case "B":
                return new Color(90, 200, 235);
            case "C":
                return Color.WHITE;
            case "D":
                return FLAME;
            default:
                return MISS;
        }
    }

    private static Color judgeColor(GameSession.Judgment j)
    {
        if (j == GameSession.Judgment.PERFECT)
        {
            return PERFECT;
        }
        if (j == GameSession.Judgment.GOOD)
        {
            return GOOD;
        }
        return MISS;
    }

    private static Color alpha(Color c, int a)
    {
        int aa = a < 0 ? 0 : Math.min(a, 255);
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), aa);
    }

    private static Color lerp(Color from, Color to, float t, int a)
    {
        float u = t < 0 ? 0 : Math.min(t, 1f);
        int r = (int) (from.getRed() + (to.getRed() - from.getRed()) * u);
        int gg = (int) (from.getGreen() + (to.getGreen() - from.getGreen()) * u);
        int b = (int) (from.getBlue() + (to.getBlue() - from.getBlue()) * u);
        return new Color(r, gg, b, Math.min(Math.max(a, 0), 255));
    }

    private static final class Shard
    {
        double x0;
        double y0;
        double vx;
        double vy;
        long born;
        Color color;
    }
}

package com.sob.runehero;

import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MidiRequest;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "RuneHero",
    description = "A Guitar Hero-style rhythm minigame played on the inventory tabs.",
    tags = {"music", "rhythm", "minigame", "guitar", "hero", "midi", "tabs"}
)
public class RuneHeroPlugin extends Plugin implements KeyListener
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private RuneHeroConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private RuneHeroOverlay overlay;
    @Inject private GameSession session;
    @Inject private MidiCacheLoader cacheLoader;
    @Inject private KeyManager keyManager;

    private ExecutorService loadExec;
    private ScheduledExecutorService pollExec;
    private boolean wasRunning; // for posting results when a chart ends (client thread only)

    @Override
    protected void startUp()
    {
        loadExec = Executors.newSingleThreadExecutor(r ->
        {
            Thread t = new Thread(r, "runehero-load");
            t.setDaemon(true);
            return t;
        });
        pollExec = Executors.newSingleThreadScheduledExecutor(r ->
        {
            Thread t = new Thread(r, "runehero-poll");
            t.setDaemon(true);
            return t;
        });
        pollExec.scheduleAtFixedRate(
            () -> clientThread.invoke(this::pollArm), 500, 250, TimeUnit.MILLISECONDS);
        overlayManager.add(overlay);
        keyManager.registerKeyListener(this);
    }

    @Override
    protected void shutDown()
    {
        keyManager.unregisterKeyListener(this);
        overlayManager.remove(overlay);
        session.stop();
        if (pollExec != null)
        {
            pollExec.shutdownNow();
            pollExec = null;
        }
        if (loadExec != null)
        {
            loadExec.shutdownNow();
            loadExec = null;
        }
    }

    @Provides
    RuneHeroConfig provideConfig(ConfigManager cm)
    {
        return cm.getConfig(RuneHeroConfig.class);
    }

    // ---- KeyListener: judging is keypress-only; we never read the active tab. ----

    @Override
    public void keyTyped(KeyEvent e)
    {
    }

    @Override
    public void keyPressed(KeyEvent e)
    {
        if (config.startKey().matches(e))
        {
            toggleSession();
            return;
        }
        if (config.analyzeKey().matches(e))
        {
            clientThread.invoke(this::analyzeCurrentTrack);
            return;
        }
        if (!session.isRunning())
        {
            return;
        }
        // Only the lanes this difficulty uses are live, so an unused lane's key can't break combo.
        Lane[] active = session.difficulty().lanes();
        if (config.requireStrum())
        {
            if (config.strumKey().matches(e))
            {
                session.onStrum(System.nanoTime());
                return;
            }
            for (Lane lane : active)
            {
                if (fretBind(lane).matches(e))
                {
                    session.setFret(lane, true);
                    return;
                }
            }
        }
        else
        {
            // No-strum: a fresh fret press is the hit. Ignore OS key auto-repeat (held key
            // re-fires keyPressed) so repeated notes need a genuine re-tap.
            for (Lane lane : active)
            {
                if (fretBind(lane).matches(e))
                {
                    if (!session.isFretHeld(lane))
                    {
                        session.setFret(lane, true);
                        session.onLaneHit(lane, System.nanoTime());
                    }
                    return;
                }
            }
        }
    }

    @Override
    public void keyReleased(KeyEvent e)
    {
        for (Lane lane : Lane.ORDER)
        {
            if (fretBind(lane).matches(e))
            {
                session.setFret(lane, false);
                return;
            }
        }
    }

    private void toggleSession()
    {
        if (session.isRunning())
        {
            session.stop();
            return;
        }
        if (session.isArmed())
        {
            session.disarm(); // press again to cancel arming
            return;
        }
        // Wait for the player to restart the track (Music off→on) so chart t=0 = audio t=0.
        session.arm();
    }

    /**
     * Client-thread poll (250ms). While armed, watch the live track: it must go quiet and come
     * back (the player toggling Music off→on) before we begin, so the chart's t=0 lands on the
     * instant the track restarts and the falling notes line up with the audio.
     */
    private void pollArm()
    {
        // Detect a chart ending (running -> not running) and post the results once.
        if (session.isRunning())
        {
            wasRunning = true;
            return;
        }
        if (wasRunning)
        {
            wasRunning = false;
            postResults();
            return;
        }
        if (!session.isArmed())
        {
            return;
        }
        List<MidiRequest> active = client.getActiveMidiRequests();
        boolean musicOn = active != null && !active.isEmpty();
        if (!musicOn)
        {
            session.setArmSawMusicOff(true);
            return;
        }
        if (!session.armSawMusicOff())
        {
            return; // music has been playing since arming — wait for an off→on toggle
        }
        long detectionNanos = System.nanoTime();
        MidiRequest req = active.get(0);
        session.disarm();
        long startNanos = detectionNanos + TimeUnit.MILLISECONDS.toNanos(config.syncOffsetMs());
        beginChart(req.getArchiveId(), req.isJingle(), startNanos);
    }

    /** Client thread: load archive bytes, then parse + chart off-thread and start at startNanos. */
    private void beginChart(int archiveId, boolean jingle, long startNanos)
    {
        byte[] bytes = cacheLoader.load(archiveId, jingle);
        if (bytes == null)
        {
            log.info("RuneHero: couldn't load music archive {} from your cache.", archiveId);
            return;
        }
        final byte[] cacheBytes = bytes;
        final Difficulty diff = config.difficulty();
        final int[] manual = manualChannels();
        loadExec.submit(() ->
        {
            try
            {
                List<NoteEvent> timeline = MidiTrackResolver.flatten(cacheBytes);
                // Channel A/B set -> use those; both -1 -> Smart auto-pick.
                int[] channels = manual.length > 0 ? manual : MapGenerator.smartChannels(timeline);
                List<ChartNote> chart = MapGenerator.generate(timeline, diff, channels);
                if (chart.isEmpty())
                {
                    log.info("RuneHero: empty chart (no notes on the chosen channel).");
                    return;
                }
                session.start(chart, diff, startNanos);
                final int noteCount = chart.size();
                final String chDesc = describeChannels(channels, MidiTrackResolver.analyze(cacheBytes));
                clientThread.invoke(() ->
                    chat("[RuneHero] " + diff + ", " + noteCount + " notes — " + chDesc + ". Go!"));
                log.debug("RuneHero: started {}-note chart ({}) from {}", noteCount, diff, chDesc);
            }
            catch (Throwable t)
            {
                log.warn("RuneHero: failed to build chart", t);
            }
        });
    }

    /** Client thread: load + analyze the current/configured track and print its channels to chat. */
    private void analyzeCurrentTrack()
    {
        List<MidiRequest> active = client.getActiveMidiRequests();
        if (active == null || active.isEmpty())
        {
            chat("RuneHero: no music playing to analyze.");
            return;
        }
        MidiRequest req = active.get(0);
        byte[] bytes = cacheLoader.load(req.getArchiveId(), req.isJingle());
        if (bytes == null)
        {
            chat("RuneHero: couldn't load the current track to analyze.");
            return;
        }
        final byte[] cacheBytes = bytes;
        loadExec.submit(() ->
        {
            try
            {
                List<ChannelInfo> infos = MidiTrackResolver.analyze(cacheBytes);
                List<NoteEvent> timeline = MidiTrackResolver.flatten(cacheBytes);
                int[] smart = MapGenerator.smartChannels(timeline);
                int[] manual = manualChannels();
                boolean isManual = manual.length > 0;
                int[] chosen = isManual ? manual : smart;
                List<ChartNote> preview = MapGenerator.generate(timeline, config.difficulty(), chosen);
                long noteGapMs = MapGenerator.longestNoteGapMs(preview);
                int gapChannel = busiestUncoveredChannelInLongestGap(preview, timeline, chosen);
                clientThread.invoke(() -> postAnalysis(infos, smart, chosen, isManual, noteGapMs, gapChannel));
            }
            catch (Throwable t)
            {
                log.warn("RuneHero: failed to analyze track", t);
            }
        });
    }

    /**
     * The non-chosen, non-drum channel that plays the most during the chart's longest note gap —
     * i.e. the instrument carrying the melody while your lanes rest. -1 if the gap is genuine silence.
     */
    private static int busiestUncoveredChannelInLongestGap(List<ChartNote> chart,
        List<NoteEvent> timeline, int[] chosen)
    {
        if (chart.size() < 2)
        {
            return -1;
        }
        long gapStart = 0;
        long gapEnd = 0;
        long longest = 0;
        for (int i = 1; i < chart.size(); i++)
        {
            long g = chart.get(i).hitTimeMs - chart.get(i - 1).hitTimeMs;
            if (g > longest)
            {
                longest = g;
                gapStart = chart.get(i - 1).hitTimeMs;
                gapEnd = chart.get(i).hitTimeMs;
            }
        }
        if (longest < 4000)
        {
            return -1;
        }
        boolean[] inChosen = new boolean[16];
        for (int c : chosen)
        {
            if (c >= 0 && c < 16)
            {
                inChosen[c] = true;
            }
        }
        int[] cnt = new int[16];
        for (NoteEvent e : timeline)
        {
            if (e.channel >= 0 && e.channel < 16 && e.channel != 9 && !inChosen[e.channel]
                && e.timestampMs > gapStart && e.timestampMs < gapEnd)
            {
                cnt[e.channel]++;
            }
        }
        int best = -1;
        int bestCnt = 0;
        for (int c = 0; c < 16; c++)
        {
            if (cnt[c] > bestCnt)
            {
                bestCnt = cnt[c];
                best = c;
            }
        }
        return bestCnt >= 4 ? best : -1;
    }

    /** Client thread: state what's actually being charted (Manual vs Smart), then the channel list. */
    private void postAnalysis(List<ChannelInfo> infos, int[] smart, int[] chosen, boolean isManual,
        long noteGapMs, int gapChannel)
    {
        if (infos.isEmpty())
        {
            chat("RuneHero: no instrument channels found in this track.");
            return;
        }
        Set<Integer> smartSet = new HashSet<>();
        for (int c : smart)
        {
            smartSet.add(c);
        }

        // What's ACTUALLY being charted (Manual channels override Smart), then Smart's suggestion.
        chat("[RuneHero] Now charting (" + (isManual ? "Manual" : "Smart") + "): "
            + describeChannels(chosen, infos) + (chosen.length >= 3 ? "  (3 lanes!)" : ""));
        if (isManual)
        {
            chat("Smart suggests: " + describeChannels(smart, infos)
                + "  (set Channel A/B/C to -1 to use it).");
        }
        chat(String.format("Longest pause between notes (this difficulty): %.1fs.", noteGapMs / 1000.0));
        if (gapChannel >= 0)
        {
            chat("During that pause, ch" + gapChannel + " " + instrumentFor(infos, gapChannel)
                + " has the melody — add it (Channel A/B/C) to fill the gap.");
        }
        chat("Channels (Smart marked; set Channel A/B/C to override):");

        // Smart-picked channels first, then the rest by descending note count.
        List<ChannelInfo> ordered = new ArrayList<>(infos);
        ordered.sort((a, b) ->
        {
            boolean sa = smartSet.contains(a.channel);
            boolean sb2 = smartSet.contains(b.channel);
            if (sa != sb2)
            {
                return sa ? -1 : 1;
            }
            return Integer.compare(b.noteCount, a.noteCount);
        });
        for (ChannelInfo ci : ordered)
        {
            String inst = ci.isDrums() ? "Percussion (drums)" : GmInstruments.name(ci.program);
            String line = "  ch" + ci.channel + "  " + inst + " - " + ci.noteCount + " notes, "
                + GmInstruments.noteName(ci.minPitch) + "-" + GmInstruments.noteName(ci.maxPitch);
            if (smartSet.contains(ci.channel))
            {
                line += "  <- SMART";
            }
            chat(line);
        }
    }

    /** Human-readable list of the channels a chart was built from, e.g. "ch3 Acoustic Grand Piano". */
    private static String describeChannels(int[] channels, List<ChannelInfo> infos)
    {
        if (channels.length == 0)
        {
            return "all instruments";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < channels.length; i++)
        {
            if (i > 0)
            {
                sb.append(" + ");
            }
            sb.append("ch").append(channels[i]).append(' ').append(instrumentFor(infos, channels[i]));
        }
        return sb.toString();
    }

    private static String instrumentFor(List<ChannelInfo> infos, int channel)
    {
        for (ChannelInfo ci : infos)
        {
            if (ci.channel == channel)
            {
                return ci.isDrums() ? "drums" : GmInstruments.name(ci.program);
            }
        }
        return "?";
    }

    /** Client thread: end-of-chart summary. */
    private void postResults()
    {
        int total = session.totalNotes();
        if (total == 0)
        {
            return;
        }
        int hits = session.hits();
        int acc = (int) Math.round(100.0 * hits / total);
        String rank = acc >= 98 ? "S" : acc >= 95 ? "A" : acc >= 88 ? "B"
            : acc >= 75 ? "C" : acc >= 60 ? "D" : "E";
        String fc = session.misses() == 0 ? "FULL COMBO! " : "";
        chat("[RuneHero] " + fc + "Rank " + rank + " — " + hits + "/" + total + " (" + acc
            + "%), max combo " + session.maxCombo() + ", score " + session.score() + ".");
    }

    private void chat(String message)
    {
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }

    /** Manually chosen channels from config A/B/C (distinct, in order); empty = Smart auto-pick. */
    private int[] manualChannels()
    {
        int[] raw = {config.channelA(), config.channelB(), config.channelC()};
        List<Integer> picked = new ArrayList<>(3);
        for (int c : raw)
        {
            if (c >= 0 && !picked.contains(c))
            {
                picked.add(c);
            }
        }
        int[] out = new int[picked.size()];
        for (int i = 0; i < out.length; i++)
        {
            out[i] = picked.get(i);
        }
        return out;
    }

    private Keybind fretBind(Lane lane)
    {
        switch (lane)
        {
            case COMBAT:
                return config.combatKey();
            case INVENTORY:
                return config.inventoryKey();
            case EQUIPMENT:
                return config.equipmentKey();
            case PRAYER:
                return config.prayerKey();
            case MAGIC:
            default:
                return config.magicKey();
        }
    }
}

package com.sob.runehero;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Comparator;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Resolves the on-screen rectangle of each of the 7 main tab buttons (Combat .. Magic)
 * for whichever client layout is active. Used ONLY to know where to draw the falling-note
 * lanes — never to read which tab is selected.
 *
 * STONE0..STONE6 are the 7 main tab "stones" in every desktop layout. We resolve all 7 and
 * sort them by canvas-X so lane 0 is always the leftmost icon, regardless of how the client
 * orders the stones internally or which layout is in use.
 */
@Singleton
final class TabBounds
{
    /** The 7 main tabs (Combat..Magic). resolve() returns this many rects, indexed by screen-X. */
    static final int MAIN_TAB_COUNT = 7;

    private static final int[] FIXED = {
        InterfaceID.Toplevel.STONE0, InterfaceID.Toplevel.STONE1, InterfaceID.Toplevel.STONE2,
        InterfaceID.Toplevel.STONE3, InterfaceID.Toplevel.STONE4, InterfaceID.Toplevel.STONE5,
        InterfaceID.Toplevel.STONE6,
    };
    private static final int[] RESIZABLE_CLASSIC = {
        InterfaceID.ToplevelOsrsStretch.STONE0, InterfaceID.ToplevelOsrsStretch.STONE1,
        InterfaceID.ToplevelOsrsStretch.STONE2, InterfaceID.ToplevelOsrsStretch.STONE3,
        InterfaceID.ToplevelOsrsStretch.STONE4, InterfaceID.ToplevelOsrsStretch.STONE5,
        InterfaceID.ToplevelOsrsStretch.STONE6,
    };
    private static final int[] RESIZABLE_MODERN = {
        InterfaceID.ToplevelPreEoc.STONE0, InterfaceID.ToplevelPreEoc.STONE1,
        InterfaceID.ToplevelPreEoc.STONE2, InterfaceID.ToplevelPreEoc.STONE3,
        InterfaceID.ToplevelPreEoc.STONE4, InterfaceID.ToplevelPreEoc.STONE5,
        InterfaceID.ToplevelPreEoc.STONE6,
    };
    private static final int[][] LAYOUTS = {FIXED, RESIZABLE_MODERN, RESIZABLE_CLASSIC};

    private final Client client;

    @Inject
    TabBounds(Client client)
    {
        this.client = client;
    }

    /**
     * @return 7 rectangles indexed by lane (left to right), or null if the tab row
     *         isn't currently visible. Call from the client thread (e.g. overlay render).
     */
    Rectangle[] resolve()
    {
        for (int[] layout : LAYOUTS)
        {
            Rectangle[] r = tryLayout(layout);
            if (r != null)
            {
                return r;
            }
        }
        return null;
    }

    private Rectangle[] tryLayout(int[] ids)
    {
        Widget[] ws = new Widget[ids.length];
        for (int i = 0; i < ids.length; i++)
        {
            int id = ids[i];
            Widget w = client.getWidget(id >>> 16, id & 0xFFFF);
            if (w == null || w.isHidden())
            {
                return null;
            }
            ws[i] = w;
        }
        Arrays.sort(ws, Comparator
            .comparingInt((Widget w) -> w.getBounds().x)
            .thenComparingInt(w -> w.getBounds().y));
        Rectangle[] out = new Rectangle[ws.length];
        for (int i = 0; i < ws.length; i++)
        {
            out[i] = ws[i].getBounds();
        }
        return out;
    }
}

